import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source (kernel and function)
elementmatmul_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void gemm_kernel(const float* A, const float* B, float* C, int total_elements) {
    // Each thread computes one element of the output matrix.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        // Infer N from total_elements assuming square matrices.
        int N = static_cast<int>(std::sqrt(total_elements));
        int row = idx / N;
        int col = idx % N;
        float sum = 0.0f;
        for (int k = 0; k < N; ++k) {
            sum += A[row * N + k] * B[k * N + col];
        }
        C[idx] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor a, torch::Tensor b) {
    int total_elements = static_cast<int>(a.numel());
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    gemm_kernel<<<num_blocks, block_size>>>(a.data_ptr<float()>, b.data_ptr<float()>, out.data_ptr<float()>, total_elements);

    return out;
}
"""

# C++ source declaration
elementmatmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor a, torch::Tensor b);"

elementmatmul = load_inline(
    name="elementmatmul",
    cpp_sources=elementmatmul_cpp_source,
    cuda_sources=elementmatmul_cuda_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul_cuda = elementmatmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul_cuda(A, B)
